20	  items: readonly Item[],
21	  previousContracts: number,
22	): number {
23	  const { basePremium, riskSurcharges } = priceItems(items);
24	
25	  const premium =
26	    basePremium +
27	    riskSurcharges +
28	    policyWideAdjustment({ customer, previousContracts }, basePremium) +
29	    PROCESSING_FEE;
30	
31	  return premiumRoundedInMHPCOsFavour(premium);
