/**
 * What an incident reports: the entries a claim is made of, and what the
 * MHPCO will accept as a well-formed one.
 *
 * Admitting a damage entry is its own decision, separate from what the entry
 * settles at. The clauses, the deductible and the cap decide what the MHPCO
 * owes for a damage it accepts; the rules here decide whether there is a
 * damage to settle at all. The MHPCO revises the two on their own schedules
 * -- a stricter report form does not change any payout, and a revised clause
 * does not change what a report must look like.
 */

export interface Damage {
  readonly itemType: string;
  readonly amount: number;
}

/**
 * The least a damage may report. A damage is an amount of harm suffered, so
 * a negative entry reports less than no harm at all: it is a malformed
 * report rather than a claim the MHPCO settles.
 *
 * This bound coincides with the floor a payout settles at, but it is a
 * different fact about a different thing -- what a report may say, not what
 * the MHPCO pays -- and the two are stated apart so that raising one (a
 * minimum reportable damage, say) leaves the other where it is.
 */
const NO_HARM_SUFFERED = 0;

/**
 * The amount a damage reports, once the report is accepted. A claim reads a
 * damage's amount through here rather than off the entry, so that no part of
 * the settlement can act on an amount the MHPCO has not admitted.
 */
export function reportedDamageAmount(damage: Damage): number {
  if (damage.amount < NO_HARM_SUFFERED) {
    throw new Error(
      `A damage cannot be a negative amount, but got ${damage.amount}`,
    );
  }
  return damage.amount;
}
import type { Item } from "./policy.js";

/**
 * Matching an incident's damage entries to the insured items they hit.
 *
 * This is its own decision, separate from what a damage settles at: it
 * answers "which covered item was this?", not "what does the MHPCO pay?".
 * Each entry consumes a distinct insured item, so an incident naming a type
 * more often than the policy covers it is refused rather than settled -- an
 * entry with no insured item left to consume has nothing to claim against.
 *
 * Which of several alike items an entry consumes is a decision in its own
 * right, and the MHPCO settles it by order: an entry takes the first item of
 * its type the policy still has unconsumed. An incident names a type, never
 * a particular sword, so the MHPCO has no other ground to choose on. The
 * choice is unobservable only while alike items settle alike; two swords at
 * different enchantment levels would make it visible, and it is stated here
 * by name so that revising it means revising this rule rather than
 * discovering it in what the matching happens to do.
 */
export function damagedItems(
  items: readonly Item[],
  itemTypes: readonly string[],
): readonly Item[] {
  const unconsumed = [...items];
  return itemTypes.map((itemType) => {
    const hit = unconsumed.findIndex((item) => item.type === itemType);
    if (hit === -1) {
      throw new Error(
        `This policy does not cover an item of type "${itemType}"`,
      );
    }
    return unconsumed.splice(hit, 1)[0];
  });
}
/**
 * The MHPCO rounds every amount in its own favour, which means opposite
 * directions on the two sides of the business: a premium is what the
 * customer pays, so it rounds up; a payout is what the MHPCO pays out, so
 * it rounds down.
 *
 * Only a final amount is rounded; every intermediate amount in a
 * calculation stays a fraction.
 */
export function premiumRoundedInMHPCOsFavour(premium: number): number {
  return Math.ceil(premium);
}

export function payoutRoundedInMHPCOsFavour(payout: number): number {
  return Math.floor(payout);
}

